], "effective_from": "2023-04-01", "effective_from_quote": "Peraturan Perusahaan ini berlaku sejak tanggal 1 April 2023 sampai dengan tanggal 31 Maret 2025.", "effective_until": "2025-03-31", "effective_until_quote": "Peraturan Perusahaan ini berlaku sejak tanggal 1 April 2023 sampai dengan tanggal 31 Maret 2025.", "subjects": [
{"kind": "employer_group", "value": "PT Lintas Gudang Nusantara", "quote": "PERATURAN PERUSAHAAN PT LINTAS GUDANG NUSANTARA PERIODE 2023-2025"}
]}

