{"relevant": true, "add": [
{"kind": "rule", "id": "PRS.SP02.JKK_RATE", "label": "company JKK premium rate 0.89%", "label_id": "tarif iuran JKK perusahaan 0,89%", "valid_from": "2023-01-01", "valid_until": "2024-12-31", "recorded_on": "2023-01-01", "fields": [{"name": "layer", "value": "company"}, {"name": "modality", "value": "default"}, {"name": "scope", "value": "period"}, {"name": "produces", "value": "jkk_rate"}, {"name": "expression", "value": "89 / 10000"}, {"name": "policy", "value": "SP02"}], "source": [{"document": "SP02", "provision": "Pasal 32 ayat (1)", "page": 1, "quote": "Iuran JKK sebesar 0,89% (nol koma delapan puluh sembilan persen), iuran JKM sebesar 0,30% (nol koma tiga puluh persen), dan iuran Jaminan Kesehatan bagian Perusahaan sebesar 4% (empat persen) dari upah sebulan ditanggung Perusahaan dan diperhitungkan sebagai penghasilan bruto pekerja."}, {"document": "SP02", "provision": "Pasal 52 ayat (1)", "page": 1, "quote": "Peraturan Perusahaan ini berlaku sejak tanggal 1 Januari 2023 sampai dengan tanggal 31 Desember 2024."}]},
{"kind": "rule", "id": "PRS.SP02.TAXABLE_ANNUALIZED", "label": "annualised taxable regular income: gross x 12 less job expense (5%, max 6,000,000 a year), JHT/JP and PTKP, rounded down to thousands", "label_id": "penghasilan kena pajak disetahunkan menurut peraturan perusahaan", "valid_from": "2023-01-01", "valid_until": "2024-12-31", "recorded_on": "2023-01-01", "fields": [{"name": "layer", "value": "company"}, {"name": "modality", "value": "default"}, {"name": "scope", "value": "period"}, {"name": "produces", "value": "taxable_regular_annualized"}, {"name": "expression", "value": "max(0, round(12 * regular_gross - min(round(5 / 100 * 12 * regular_gross, 1, 'down'), 6000000) - 12 * employee_pension_contributions - ptkp_amount, 1000, 'down'))"}, {"name": "condition", "value": "not is_final_period"}, {"name": "policy", "value": "SP02"}], "source": [{"document": "SP02", "provision": "Pasal 31 ayat (2)", "page": 1, "quote": "Pajak Penghasilan Pasal 21 atas penghasilan teratur pada setiap Masa Pajak Januari sampai dengan November dihitung dengan cara: a. penghasilan bruto teratur sebulan dikalikan 12 (dua belas); b. dikurangi biaya jabatan sebesar 5% (lima persen) paling banyak Rp6.000.000,00 (enam juta rupiah) setahun, iuran JHT dan JP bagian pekerja setahun, dan Penghasilan Tidak Kena Pajak; c. Penghasilan Kena Pajak dibulatkan ke bawah hingga ribuan rupiah penuh"}, {"document": "SP02", "provision": "Pasal 52 ayat (1)", "page": 1, "quote": "Peraturan Perusahaan ini berlaku sejak tanggal 1 Januari 2023 sampai dengan tanggal 31 Desember 2024."}]},
{"kind": "rule", "id": "PRS.SP02.PPH_ANNUAL", "label": "annual tax on annualised regular income at the Article 17(1)(a) rates", "label_id": "PPh setahun atas penghasilan teratur yang disetahunkan dengan tarif Pasal 17 ayat (1) huruf a", "valid_from": "2023-01-01", "valid_until": "2024-12-31", "recorded_on": "2023-01-01", "fields": [{"name": "layer", "value": "company"}, {"name": "modality", "value": "default"}, {"name": "scope", "value": "period"}, {"name": "produces", "value": "pph_regular_annual"}, {"name": "expression", "value": "round(progressive('pasal17', taxable_regular_annualized), 1, 'down')"}, {"name": "condition", "value": "not is_final_period"}, {"name": "policy", "value": "SP02"}], "source": [{"document": "SP02", "provision": "Pasal 31 ayat (2) huruf d", "page": 1, "quote": "d. dikenai tarif Pasal 17 ayat (1) huruf a Undang-Undang Pajak Penghasilan"}, {"document": "SP02", "provision": "Pasal 31 ayat (5)", "page": 1, "quote": "Tata cara sebagaimana dimaksud pada ayat (2) sampai dengan ayat (4) berlaku selama masa berlaku Peraturan Perusahaan ini."}, {"document": "SP02", "provision": "Pasal 52 ayat (1)", "page": 1, "quote": "Peraturan Perusahaan ini berlaku sejak tanggal 1 Januari 2023 sampai dengan tanggal 31 Desember 2024."}]},
{"kind": "rule", "id": "PRS.SP02.PPH_MONTH", "label": "monthly tax on regular income: annual tax divided by 12", "label_id": "PPh sebulan atas penghasilan teratur: PPh setahun dibagi 12", "valid_from": "2023-01-01", "valid_until": "2024-12-31", "recorded_on": "2023-01-01", "fields": [{"name": "layer", "value": "company"}, {"name": "modality", "value": "default"}, {"name": "scope", "value": "period"}, {"name": "produces", "value": "pph_regular_month"}, {"name": "expression", "value": "round(pph_regular_annual / 12, 1, param('pph_round_mode'))"}, {"name": "condition", "value": "not is_final_period"}, {"name": "policy", "value": "SP02"}], "source": [{"document": "SP02", "provision": "Pasal 31 ayat (2) huruf d dan e", "page": 1, "quote": "d. dikenai tarif Pasal 17 ayat (1) huruf a Undang-Undang Pajak Penghasilan; dan e. hasilnya dibagi 12 (dua belas)."}, {"document": "SP02", "provision": "Pasal 52 ayat (1)", "page": 1, "quote": "Peraturan Perusahaan ini berlaku sejak tanggal 1 Januari 2023 sampai dengan tanggal 31 Desember 2024."}]},
{"kind": "rule", "id": "PRS.SP02.PPH_IRREGULAR", "label": "tax on irregular income (bonus, THR): annual tax on annualised regular plus irregular income minus annual tax on annualised regular income", "label_id": "PPh atas penghasilan tidak teratur menurut peraturan perusahaan", "valid_from": "2023-01-01", "valid_until": "2024-12-31", "recorded_on": "2023-01-01", "fields": [{"name": "layer", "value": "company"}, {"name": "modality", "value": "default"}, {"name": "scope", "value": "period"}, {"name": "produces", "value": "pph_irregular_month"}, {"name": "expression", "value": "round(progressive('pasal17', max(0, round(12 * regular_gross + irregular_gross - min(round(5 / 100 * (12 * regular_gross + irregular_gross), 1, 'down'), 6000000) - 12 * employee_pension_contributions - ptkp_amount, 1000, 'down'))), 1, 'down') - round(progressive('pasal17', max(0, round(12 * regular_gross - min(round(5 / 100 * 12 * regular_gross, 1, 'down'), 6000000) - 12 * employee_pension_contributions - ptkp_amount, 1000, 'down'))), 1, 'down')"}, {"name": "condition", "value": "not is_final_period"}, {"name": "policy", "value": "SP02"}], "source": [{"document": "SP02", "provision": "Pasal 31 ayat (3)", "page": 1, "quote": "Pajak Penghasilan Pasal 21 atas penghasilan tidak teratur, termasuk bonus tahunan dan Tunjangan Hari Raya Keagamaan, sebesar selisih antara Pajak Penghasilan setahun atas penghasilan teratur yang disetahunkan ditambah penghasilan tidak teratur dengan Pajak Penghasilan setahun atas penghasilan teratur yang disetahunkan."}, {"document": "SP02", "provision": "Pasal 31 ayat (2) huruf b", "page": 1, "quote": "b. dikurangi biaya jabatan sebesar 5% (lima persen) paling banyak Rp6.000.000,00 (enam juta rupiah) setahun, iuran JHT dan JP bagian pekerja setahun, dan Penghasilan Tidak Kena Pajak"}, {"document": "SP02", "provision": "Pasal 52 ayat (1)", "page": 1, "quote": "Peraturan Perusahaan ini berlaku sejak tanggal 1 Januari 2023 sampai dengan tanggal 31 Desember 2024."}]},
{"kind": "rule", "id": "PRS.SP02.PPH_DUE_RUNNING", "label": "PPh 21 withheld each month January-November: regular plus irregular part, for the whole policy period", "label_id": "PPh Pasal 21 dipotong setiap bulan Januari sampai November", "valid_from": "2023-01-01", "valid_until": "2024-12-31", "recorded_on": "2023-01-01", "fields": [{"name": "layer", "value": "company"}, {"name": "modality", "value": "default"}, {"name": "scope", "value": "period"}, {"name": "produces", "value": "pph21_due"}, {"name": "expression", "value": "pph_regular_month + pph_irregular_month"}, {"name": "condition", "value": "not is_final_period"}, {"name": "policy", "value": "SP02"}], "source": [{"document": "SP02", "provision": "Pasal 31 ayat (1)", "page": 1, "quote": "Pajak Penghasilan Pasal 21 dipotong setiap bulan dari penghasilan pekerja."}, {"document": "SP02", "provision": "Pasal 31 ayat (5)", "page": 1, "quote": "Tata cara sebagaimana dimaksud pada ayat (2) sampai dengan ayat (4) berlaku selama masa berlaku Peraturan Perusahaan ini."}, {"document": "SP02", "provision": "Pasal 52 ayat (1)", "page": 1, "quote": "Peraturan Perusahaan ini berlaku sejak tanggal 1 Januari 2023 sampai dengan tanggal 31 Desember 2024."}]}
